        "평가사유": "[화제성 7점] 확정 사실 → 참조 데이터 IP.json에서 '짱구는 못말려'는 톱급 IP로, '한국 가족·어린이 시청층 톱, 극장판 안정 흥행'으로 분류돼 있다. 일본에서는 2026-07-31 개봉해 흥행수입 약 28.9억 엔으로 극장판 시리즈 역대 1위를 기록했다(나무위키, 보조 출처).\n추정 → 일본 흥행 기록이 국내 홍보 포인트가 되겠지만, 국내 관객층은 어린이·가족과 팬층에 몰려 있어 7점으로 제한했다.\n[독창성 6점] 확정 사실 → 33번째 극장판으로 '요괴'라는 테마를 새로 내세웠다.\n매년 나오는 시리즈 포맷이라 대체 불가성은 낮다. 시리즈 최고 흥행작이라는 점만 가점으로 반영했다.\n[근접성 8점] 확정 사실 → 기존 국내 성우진의 한국어 더빙으로 극장 개봉하며, 오랜 국내 방영으로 친숙한 IP다(KOBIS 국내 제목 등록, 상태 '개봉예정').\n일본 작품이고 정서가 일본 시골 배경이라 9점 이상은 주지 않았다.\n[영향성 6점] 추정 → 겨울방학 초입 가족 관객 수요를 흡수할 가능성이 있다.\n다만 극장판이 매년 반복되고, 직전작(떡잎마을 댄서즈)이 2025-12-24 국내 개봉해 피로도가 있을 수 있다. 확산 범위도 가족층에 한정된다.\n[종합] 강점: 톱급 IP, 일본 역대 시리즈 최고 흥행. 약점: 국내 개봉일 12/3은 TMDB·나무위키 기준이며 언론 보도로는 확인하지 못했다. 연례 시리즈라 새로움이 약하다. 편성 관점: 12월 초 가족 애니 꼭지로 무난하다.",
