        "평가사유": "[화제성 6점] (확정 사실 →) KBS가 약 300억 원을 투입한 3년 만의 대하사극으로, 몽골 로케를 마치고 2026-11-14 첫 방송을 확정했다. 장혁(연개소문)·김강우(김춘추)·박성웅(김유신) 등 중견 캐스팅이 공개됐다. (추정 →) 다만 주연 이현욱의 대중 인지도가 제한적이고 대하사극 시청층이 고령화돼 있어 7점 이상은 근거가 약하다.\n[독창성 6점] (확정 사실 →) 삼국통일은 여러 번 다뤄진 소재지만 문무왕 김법민을 주인공으로 세운 대하사극은 드물다. 300억 규모의 전쟁 스케일은 현재 지상파에서 유일한 시도다.\n[근접성 8점] (확정 사실 →) 한국사 정통 소재이고 지상파 무료 시청이라 접근성이 매우 높다. 다만 젊은층과의 정서적 거리는 있어 9점은 아니다.\n[영향성 6점] (추정 →) 대하사극 부활 여부라는 방송계 의제를 만들고, 성공 시 지상파 편성 전략에 파급이 있다. 사회적 의제화는 제한적.\n[종합] 강점: 제작비·스케일·지상파 접근성. 약점: 대하사극의 구조적 시청층 축소와 주연 인지도 부족, 사극 고증 논란 리스크. 편성 관점: 11월 중순 지상파 대표 카드로는 유효하나 화제성 기대치는 낮춰 잡아야 한다.",
